package com.booksyde.repository; import com.booksyde.entity.CommentEntity; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; public interface CommentRepository extends JpaRepository<CommentEntity,UUID>{List<CommentEntity> findAllByMangaIdAndVolumeIdOrderByCreatedAtDesc(UUID mangaId,UUID volumeId); List<CommentEntity> findAllByMangaIdAndVolumeIdIsNullOrderByCreatedAtDesc(UUID mangaId);}